  type(fv_flags_type), intent(inout) :: flagstruct
  type(fv_grid_type), intent(in), target :: gridstruct
  real, intent(in) :: hs(isd:ied,jsd:jed)
  logical, intent(in) :: hybrid_z
  logical, intent(in) :: hydrostatic
  integer, intent(in) :: kord_mt
  integer, intent(in) :: kord_tm
  integer, intent(in) :: nq
  integer, intent(in) :: kord_tr(nq)
  integer, intent(in) :: kord_wz
  logical, intent(in) :: last_step
  real, intent(in) :: mdt
  real,optional, intent(inout) :: mfx(is:ie+1,js:je,km)
  real,optional, intent(inout) :: mfy(is:ie,js:je+1,km)
  integer, intent(in) :: ng
  integer, intent(in) :: nwat
  real, intent(inout) :: omga(isd:ied,jsd:jed,km)
  logical, intent(in) :: out_dt
  real, intent(in) :: pdt
  real, intent(inout) :: pe(is-1:ie+1,km+1,js-1:je+1)
  real, intent(inout) :: peln(is:ie,km+1,js:je)
  real, intent(in) :: pfull(km)
  real, intent(inout) :: pk(is:ie,js:je,km+1)
  real, intent(out) :: pkz(is:ie,js:je,km)
  real, intent(inout) :: ps(isd:ied,jsd:jed)
  real, intent(inout) :: pt(isd:ied,jsd:jed,km)
  real, intent(in) :: ptop
  real, intent(inout) :: q(isd:ied,jsd:jed,km,*)
  real, intent(inout) :: q_con(isd:,jsd:,1:)
  real, intent(in) :: r_vir
  integer, intent(in) :: remap_option
  logical, intent(in) :: reproduce_sum
  integer, intent(in) :: sphum
  real, intent(out) :: te(isd:ied,jsd:jed,km)
  real, intent(inout) :: te0_2d(is:ie,js:je)
  real, intent(inout) :: u(isd:ied,jsd:jed+1,km)
  real, intent(inout) :: ua(isd:ied,jsd:jed,km)
  real, intent(inout) :: v(isd:ied+1,jsd:jed,km)
  real, intent(inout) :: va(isd:ied,jsd:jed,km)
  real, intent(inout) :: w(isd:,jsd:,1:)
  real, intent(in) :: ws(is:ie,js:je)

!==============================================
! declare local variables
!==============================================
  real :: bkh
  integer :: cld_amt
  real :: dlnp
  real :: dp2(is:ie,km)
  real :: dpln(is:ie,js:je)
  real :: dtmp
  logical :: fast_mp_consv
  integer :: graupel
  real :: gz(is:ie)
  logical :: help_h
  integer :: help_i
  integer :: help_j
  integer :: help_k
  integer :: help_l
  integer :: help_m
  integer :: help_n
  integer :: help_o
  integer :: help_p
  integer :: help_q
  integer :: help_r
  integer :: help_s
  integer :: help_t
  integer :: help_u
  real :: help_v
  integer :: i
  integer :: ice_wat
  integer :: iq
  integer :: j
  integer :: k
  real :: k1k
  integer :: k_next
  integer :: kmp
  integer :: kp
  integer :: liq_wat
  integer :: n
  real :: pe0(is:ie+1,km+1)
  real :: pe1(is:ie,km+1)
  real :: pe2(is:ie,km+1)
  real :: pe3(is:ie+1,km+1)
  real :: phis(is:ie,km+1)
  real :: pk1(is:ie,km+1)
  real :: pk2(is:ie,km+1)
  real :: pn2(is:ie,km+1)
  real :: q2(is:ie,km)
  integer :: rainwat
  real :: rcp
  logical :: remap_pt
  logical :: remap_t
  logical :: remap_te
  real :: rg
  real :: rrg
  integer :: snowwat
  real :: te_2d(is:ie,js:je)
  real :: tmp
  real :: tpe
  real :: zsum0(is:ie,js:je)
  real :: zsum1(is:ie,js:je)

  remap_t =  .false. 
  remap_pt =  .false. 
  remap_te =  .false. 
  select case ( remap_option )
  case (0)
    remap_t =  .true. 
  case (1)
    remap_pt =  .true. 
  case (2)
    remap_te =  .true. 
  case default
    print *, ' INVALID REMAPPING OPTION '
    stop
  end select
  help_h = is_master() .and. flagstruct%fv_debug
  if (help_h) then
    print *, ''
    select case ( remap_option )
    case (0)
      print *, ' REMAPPING  T in logP '
    case (1)
      print *, ' REMAPPING PT in P'
    case (2)
      print *, ' REMAPPING TE in logP with GMAO cubic'
    end select
    print *, ' REMAPPING CONSV:     ',consv
    print *, ' REMAPPING CONSV_MIN: ',consv_min
    print *, ''
  endif
  k1k = rdgas/cv_air
  rg = rdgas
  rcp = 1./cp
  rrg = -(rdgas/grav)
  liq_wat = get_tracer_index(model_atmos,'liq_wat')
  ice_wat = get_tracer_index(model_atmos,'ice_wat')
  rainwat = get_tracer_index(model_atmos,'rainwat')
  snowwat = get_tracer_index(model_atmos,'snowwat')
  graupel = get_tracer_index(model_atmos,'graupel')
  cld_amt = get_tracer_index(model_atmos,'cld_amt')
  if (do_sat_adj) then
    fast_mp_consv = ( .not. do_adiabatic_init) .and. consv > consv_min
    do k = 1, km
      kmp = k
      if (pfull(k) > 10.e2) then
        exit
      endif
    end do
    call qs_init( kmp )
  endif
  do j = js, je+1
    do k = 1, km+1
      do i = is, ie
        pe1(i,k) = pe(i,k,j)
      end do
    end do
    do i = is, ie
      pe2(i,1) = ptop
      pe2(i,km+1) = pe(i,km+1,j)
    end do
    if (j /= je+1) then
      if (remap_t) then
        if (hydrostatic) then
          do k = 1, km
            do i = is, ie
              pt(i,j,k) = pt(i,j,k)*(pk(i,j,k+1)-pk(i,j,k))/(akap*(peln(i,k+1,j)-peln(i,k,j)))
            end do
          end do
        else
          do k = 1, km
            do i = is, ie
              pt(i,j,k) = pt(i,j,k)*exp(k1k*log(rrg*delp(i,j,k)/delz(i,j,k)*pt(i,j,k)))
            end do
          end do
        endif
      else if (remap_pt) then
      else if (remap_te) then
        call pkez( km,is,ie,js,je,j,pe,pk,akap,peln,pkz,ptop )
        do k = 1, km
          do i = is, ie
            te(i,j,k) = 0.25*gridstruct%rsin2(i,j)*(u(i,j,k)**2+u(i,j+1,k)**2+v(i,j,k)**2+v(i+1,j,k)**2-(u(i,j,k)+u(i,j+1,k))*(v(i,j,k)+v(i+1,j,k))*gridstruct%cosa_s(i,j))+cp_air*pt(i,j,k)*pkz(i,j,k)
          end do
        end do
      endif
      if ( .not. hydrostatic) then
        do k = 1, km
          do i = is, ie
            delz(i,j,k) = -(delz(i,j,k)/delp(i,j,k))
          end do
        end do
      endif
      do i = is, ie
        ps(i,j) = pe1(i,km+1)
      end do
      do k = 2, km
        do i = is, ie
          pe2(i,k) = ak(k)+bk(k)*pe(i,km+1,j)
        end do
      end do
      do k = 1, km
        do i = is, ie
          dp2(i,k) = pe2(i,k+1)-pe2(i,k)
        end do
      end do
      do k = 1, km
        do i = is, ie
          delp(i,j,k) = dp2(i,k)
        end do
      end do
      do k = 1, km+1
        do i = is, ie
          pk1(i,k) = pk(i,j,k)
        end do
      end do
      do i = is, ie
        pn2(i,1) = peln(i,1,j)
        pn2(i,km+1) = peln(i,km+1,j)
        pk2(i,1) = pk1(i,1)
        pk2(i,km+1) = pk1(i,km+1)
      end do
      do k = 2, km
        do i = is, ie
          pn2(i,k) = log(pe2(i,k))
          pk2(i,k) = exp(akap*pn2(i,k))
        end do
      end do
      if (remap_t) then
        help_i = abs(kord_tm)
        call map_scalar( km,peln(is,1,j),pt,gz,km,pn2,pt,is,ie,j,isd,ied,jsd,jed,1,help_i,t_min )
      else if (remap_pt) then
        help_j = abs(kord_tm)
        call map1_ppm( km,pe1,pt,gz,km,pe2,pt,is,ie,j,isd,ied,jsd,jed,1,help_j )
      else if (remap_te) then
        do i = is, ie
          phis(i,km+1) = hs(i,j)
        end do
        do k = km, 1, -1
          do i = is, ie
            phis(i,k) = phis(i,k+1)+cp_air*pt(i,j,k)*(pk1(i,k+1)-pk1(i,k))
          end do
        end do
        do k = 1, km+1
          do i = is, ie
            phis(i,k) = phis(i,k)*pe1(i,k)
          end do
        end do
        do k = 1, km
          do i = is, ie
            te(i,j,k) = te(i,j,k)+(phis(i,k+1)-phis(i,k))/(pe1(i,k+1)-pe1(i,k))
          end do
        end do
        call map1_cubic( km,pe1,te,km,pe2,te,is,ie,j,isd,ied,jsd,jed,akap,t_var=1,conserv= .true.  )
      endif
      if (nq > 5) then
        call mapn_tracer( nq,km,pe1,pe2,q,dp2,kord_tr,j,is,ie,isd,ied,jsd,jed,0.,fill )
      else if (nq > 0) then
        do iq = 1, nq
          call map1_q2( km,pe1,q(isd,jsd,1,iq),km,pe2,q2,dp2,is,ie,0,kord_tr(iq),j,isd,ied,jsd,jed,0. )
          if (fill) then
            help_k = ie-is+1
            call fillz( help_k,km,1,q2,dp2 )
          endif
          do k = 1, km
            do i = is, ie
              q(i,j,k,iq) = q2(i,k)
            end do
          end do
        end do
      endif
      if ( .not. hydrostatic) then
        call map1_ppm( km,pe1,w,ws(is,j),km,pe2,w,is,ie,j,isd,ied,jsd,jed,-2,kord_wz )
        help_l = abs(kord_tm)
        call map1_ppm( km,pe1,delz,gz,km,pe2,delz,is,ie,j,isd,ied,jsd,jed,1,help_l )
        do k = 1, km
          do i = is, ie
            delz(i,j,k) = -(delz(i,j,k)*dp2(i,k))
          end do
        end do
      endif
      do k = 1, km+1
        do i = is, ie
          pk(i,j,k) = pk2(i,k)
        end do
      end do
      if (do_omega) then
        do i = is, ie
          pe3(i,1) = 0.
        end do
        do k = 2, km+1
          do i = is, ie
            pe3(i,k) = omga(i,j,k-1)
          end do
        end do
      endif
      do k = 1, km+1
        do i = is, ie
          pe0(i,k) = peln(i,k,j)
          peln(i,k,j) = pn2(i,k)
        end do
      end do
      if (hydrostatic) then
        do k = 1, km
          do i = is, ie
            pkz(i,j,k) = (pk2(i,k+1)-pk2(i,k))/(akap*(peln(i,k+1,j)-peln(i,k,j)))
          end do
          if (remap_pt .and. last_step .and. ( .not. adiabatic)) then
            do i = is, ie
              pt(i,j,k) = pt(i,j,k)*pkz(i,j,k)
            end do
          endif
        end do
      else
        if (remap_te) then
          print *, 'TE remapping non-hydrostatic is invalid and cannot be run'
          stop
        endif
        if (remap_t) then
          do k = 1, km
            do i = is, ie
              pkz(i,j,k) = exp(akap*log(rrg*delp(i,j,k)/delz(i,j,k)*pt(i,j,k)))
            end do
          end do
        else
          do k = 1, km
            do i = is, ie
              pkz(i,j,k) = exp(k1k*log(rrg*delp(i,j,k)/delz(i,j,k)*pt(i,j,k)))
            end do
            if (last_step .and. ( .not. adiabatic)) then
              do i = is, ie
pt(i,j,k) = pt(i,j,k)*pkz(i,j,k)
              end do
            endif
          end do
        endif
      endif
      if (do_omega) then
        do k = 1, km
          do i = is, ie
            dp2(i,k) = 0.5*(peln(i,k,j)+peln(i,k+1,j))
          end do
        end do
        do i = is, ie
          k_next = 1
          do n = 1, km
            kp = k_next
            do k = kp, km
              if (dp2(i,n) <= pe0(i,k+1) .and. dp2(i,n) >= pe0(i,k)) then
omga(i,j,n) = pe3(i,k)+(pe3(i,k+1)-pe3(i,k))*(dp2(i,n)-pe0(i,k))/(pe0(i,k+1)-pe0(i,k))
k_next = k
exit
              endif
            end do
          end do
        end do
      endif
    endif
    do i = is, ie+1
      pe0(i,1) = pe(i,1,j)
    end do
    do k = 2, km+1
      do i = is, ie
        pe0(i,k) = 0.5*(pe(i,k,j-1)+pe1(i,k))
      end do
    end do
    do k = 1, km+1
      bkh = 0.5*bk(k)
      do i = is, ie
        pe3(i,k) = ak(k)+bkh*(pe(i,km+1,j-1)+pe1(i,km+1))
      end do
    end do
    help_m = jed+1
    call map1_ppm( km,pe0(is:ie,:),u,gz,km,pe3(is:ie,:),u,is,ie,j,isd,ied,jsd,help_m,-1,kord_mt )
    if (present(mfy)) then
      help_n = je+1
      call map1_ppm( km,pe0(is:ie,:),mfy,gz,km,pe3(is:ie,:),mfy,is,ie,j,is,ie,js,help_n,-1,kord_mt )
    endif
    if (present(cy)) then
      help_o = je+1
      call map1_ppm( km,pe0(is:ie,:),cy,gz,km,pe3(is:ie,:),cy,is,ie,j,isd,ied,js,help_o,-1,kord_mt )
    endif
    if (j < je+1) then
      do i = is, ie+1
        pe3(i,1) = ak(1)
      end do
      do k = 2, km+1
        bkh = 0.5*bk(k)
        do i = is, ie+1
          pe0(i,k) = 0.5*(pe(i-1,k,j)+pe(i,k,j))
          pe3(i,k) = ak(k)+bkh*(pe(i-1,km+1,j)+pe(i,km+1,j))
        end do
      end do
      help_p = ie+1
      help_q = ied+1
      call map1_ppm( km,pe0,v,gz,km,pe3,v,is,help_p,j,isd,help_q,jsd,jed,-1,kord_mt )
      if (present(mfx)) then
        help_r = ie+1
        help_s = ie+1
        call map1_ppm( km,pe0,mfx,gz,km,pe3,mfx,is,help_r,j,is,help_s,js,je,-1,kord_mt )
      endif
      if (present(cx)) then
        help_t = ie+1
        help_u = ie+1
        call map1_ppm( km,pe0,cx,gz,km,pe3,cx,is,help_t,j,is,help_u,jsd,jed,-1,kord_mt )
      endif
    endif
    do k = 1, km
      do i = is, ie
        ua(i,j,k) = pe2(i,k+1)
      end do
    end do
  end do
  do k = 2, km
    do j = js, je
      do i = is, ie
        pe(i,k,j) = ua(i,j,k-1)
      end do
    end do
  end do
  dtmp = 0.
  if (last_step .and. ( .not. do_adiabatic_init)) then
    if (consv > consv_min) then
      do j = js, je
        if (remap_te) then
          do i = is, ie
            te_2d(i,j) = te(i,j,1)*delp(i,j,1)
          end do
          do k = 2, km
            do i = is, ie
              te_2d(i,j) = te_2d(i,j)+te(i,j,k)*delp(i,j,k)
            end do
          end do
        else
          if (hydrostatic) then
            do i = is, ie
              gz(i) = hs(i,j)
              do k = 1, km
gz(i) = gz(i)+rg*pt(i,j,k)*(peln(i,k+1,j)-peln(i,k,j))
              end do
            end do
            do i = is, ie
              te_2d(i,j) = pe(i,km+1,j)*hs(i,j)-pe(i,1,j)*gz(i)
            end do
            do k = 1, km
              do i = is, ie
te_2d(i,j) = te_2d(i,j)+delp(i,j,k)*(cp*pt(i,j,k)+0.25*gridstruct%rsin2(i,j)*(u(i,j,k)**2+u(i,j+1,k)**2+v(i,j,k)**2+v(i+1,j,k)**2-(u(i,j,k)+u(i,j+1,k))*(v(i,j,k)+v(i+1,j,k))*gridstruct%cosa_s(i,j)))
              end do
            end do
          else
            do i = is, ie
              te_2d(i,j) = 0.
              phis(i,km+1) = hs(i,j)
            end do
            do k = km, 1, -1
              do i = is, ie
phis(i,k) = phis(i,k+1)-grav*delz(i,j,k)
              end do
            end do
            do k = 1, km
              do i = is, ie
te_2d(i,j) = te_2d(i,j)+delp(i,j,k)*(cv_air*pt(i,j,k)/(1.+r_vir*q(i,j,k,sphum))+0.5*(phis(i,k)+phis(i,k+1)+w(i,j,k)**2+0.5*gridstruct%rsin2(i,j)*(u(i,j,k)**2+u(i,j+1,k)**2+v(i,j,k)**2+v(i+1,j,k)**2-(u(i,j,k)+u(i,j+1,k))*(v(i,j,k)+v(i+1,j,k))*gridstruct%cosa_s(i,j))))
              end do
            end do
          endif
        endif
        do i = is, ie
          te_2d(i,j) = te0_2d(i,j)-te_2d(i,j)
          zsum1(i,j) = pkz(i,j,1)*delp(i,j,1)
        end do
        do k = 2, km
          do i = is, ie
            zsum1(i,j) = zsum1(i,j)+pkz(i,j,k)*delp(i,j,k)
          end do
        end do
        if (hydrostatic) then
          do i = is, ie
            zsum0(i,j) = ptop*(pk(i,j,1)-pk(i,j,km+1))+zsum1(i,j)
          end do
        endif
      end do
      tpe = consv*g_sum(domain,te_2d,is,ie,js,je,ng,gridstruct%area_64,0,reproduce= .true. )
      e_flux = tpe/(grav*pdt*4.*pi*radius**2)
      if (hydrostatic) then
        dtmp = tpe/(cp*g_sum(domain,zsum0,is,ie,js,je,ng,gridstruct%area_64,0,reproduce= .true. ))
      else
        dtmp = tpe/(cv_air*g_sum(domain,zsum1,is,ie,js,je,ng,gridstruct%area_64,0,reproduce= .true. ))
      endif
    else if (consv < (-consv_min)) then
      do j = js, je
        do i = is, ie
          zsum1(i,j) = pkz(i,j,1)*delp(i,j,1)
        end do
        do k = 2, km
          do i = is, ie
            zsum1(i,j) = zsum1(i,j)+pkz(i,j,k)*delp(i,j,k)
          end do
        end do
        if (hydrostatic) then
          do i = is, ie
            zsum0(i,j) = ptop*(pk(i,j,1)-pk(i,j,km+1))+zsum1(i,j)
          end do
        endif
      end do
      e_flux = consv
      if (hydrostatic) then
        dtmp = e_flux*(grav*pdt*4.*pi*radius**2)/(cp*g_sum(domain,zsum0,is,ie,js,je,ng,gridstruct%area_64,0,reproduce= .true. ))
      else
        dtmp = e_flux*(grav*pdt*4.*pi*radius**2)/(cv_air*g_sum(domain,zsum1,is,ie,js,je,ng,gridstruct%area_64,0,reproduce= .true. ))
      endif
    endif
  endif
  if (do_sat_adj) then
    call timing_on( 'sat_adj2' )
    do k = kmp, km
      do j = js, je
        do i = is, ie
          dpln(i,j) = peln(i,k+1,j)-peln(i,k,j)
        end do
      end do
      help_v = abs(mdt)
      call fv_sat_adj( help_v,r_vir,is,ie,js,je,ng,hydrostatic,fast_mp_consv,te(isd,jsd,k),q(isd,jsd,k,sphum),q(isd,jsd,k,liq_wat),q(isd,jsd,k,ice_wat),q(isd,jsd,k,rainwat),q(isd,jsd,k,snowwat),q(isd,jsd,k,graupel),hs,dpln,delz(isd:,jsd:,k),pt(isd,jsd,k),delp(isd,jsd,k),q_con(isd:,jsd:,k),cappa(isd:,jsd:,k),gridstruct%area_64,dtdt(is:,js:,k),out_dt,last_step,cld_amt > 0,q(isd,jsd,k,cld_amt) )
      if ( .not. hydrostatic) then
        do j = js, je
          do i = is, ie
            pkz(i,j,k) = exp(akap*log(rrg*delp(i,j,k)/delz(i,j,k)*pt(i,j,k)))
          end do
        end do
      endif
    end do
    if (fast_mp_consv) then
      do j = js, je
        do i = is, ie
          do k = kmp, km
            te0_2d(i,j) = te0_2d(i,j)+te(i,j,k)
          end do
        end do
      end do
    endif
    call timing_off( 'sat_adj2' )
  endif
  if (last_step) then
    if (remap_te) then
      do j = js, je
        do i = is, ie
          gz(i) = hs(i,j)
        end do
        do k = km, 1, -1
          do i = is, ie
