  real :: ql(is:ie)
  real :: qs(is:ie)
  real :: qv(is:ie)

  select case ( nwat )
  case (1)
    do i = is, ie
      qv(i) = q(i,j,k,sphum)
      cvm(i) = (1.-qv(i))*cv_air+qv(i)*cv_vap
    end do
  case (2)
    if (present(t1)) then
      do i = is, ie
        qd(i) = max(0.,q(i,j,k,liq_wat))
        if (t1(i) > tice) then
          qs(i) = 0.
        else if (t1(i) < tice-t_i0) then
          qs(i) = qd(i)
        else
          qs(i) = qd(i)*(tice-t1(i))/t_i0
        endif
        ql(i) = qd(i)-qs(i)
        qv(i) = max(0.,q(i,j,k,sphum))
        cvm(i) = (1.-(qv(i)+qd(i)))*cv_air+qv(i)*cv_vap+ql(i)*c_liq+qs(i)*c_ice
      end do
    else
      do i = is, ie
        qv(i) = max(0.,q(i,j,k,sphum))
        qs(i) = max(0.,q(i,j,k,liq_wat))
        qd(i) = qs(i)
        cvm(i) = (1.-qv(i))*cv_air+qv(i)*cv_vap
      end do
    endif
  case (3)
    do i = is, ie
      qv(i) = q(i,j,k,sphum)
      ql(i) = q(i,j,k,liq_wat)
      qs(i) = q(i,j,k,ice_wat)
      qd(i) = ql(i)+qs(i)
      cvm(i) = (1.-(qv(i)+qd(i)))*cv_air+qv(i)*cv_vap+ql(i)*c_liq+qs(i)*c_ice
    end do
  case (4)
    do i = is, ie
      qv(i) = q(i,j,k,sphum)
      qd(i) = q(i,j,k,liq_wat)+q(i,j,k,rainwat)
      cvm(i) = (1.-(qv(i)+qd(i)))*cv_air+qv(i)*cv_vap+qd(i)*c_liq
    end do
  case (5)
    do i = is, ie
      qv(i) = q(i,j,k,sphum)
      ql(i) = q(i,j,k,liq_wat)+q(i,j,k,rainwat)
      qs(i) = q(i,j,k,ice_wat)+q(i,j,k,snowwat)
      qd(i) = ql(i)+qs(i)
      cvm(i) = (1.-(qv(i)+qd(i)))*cv_air+qv(i)*cv_vap+ql(i)*c_liq+qs(i)*c_ice
    end do
  case (6)
    do i = is, ie
      qv(i) = q(i,j,k,sphum)
      ql(i) = q(i,j,k,liq_wat)+q(i,j,k,rainwat)
      qs(i) = q(i,j,k,ice_wat)+q(i,j,k,snowwat)+q(i,j,k,graupel)
      qd(i) = ql(i)+qs(i)
      cvm(i) = (1.-(qv(i)+qd(i)))*cv_air+qv(i)*cv_vap+ql(i)*c_liq+qs(i)*c_ice
    end do
  case default
    do i = is, ie
      qd(i) = 0.
      cvm(i) = cv_air
    end do
  end select
  end subroutine moist_cv
