      c1 = 4.*(a4(2,i,3)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
      c3 = dq-0.5*c1*(d2*(5.*d1+d2)-3.*d1*d1)
      a4(2,i,2) = qm-0.25*c1*d1*d2*(d2+3.*d1)
      a4(2,i,1) = d1*(2.*c1*d1**2-c3)+a4(2,i,2)
      a4(2,i,2) = max(a4(2,i,2),min(a4(1,i,1),a4(1,i,2)))
      a4(2,i,2) = min(a4(2,i,2),max(a4(1,i,1),a4(1,i,2)))
      dc(i,1) = 0.5*(a4(2,i,2)-a4(1,i,1))
    end do
    if (iv == 0) then
      do i = i1, i2
        a4(2,i,1) = max(0.,a4(2,i,1))
        a4(2,i,2) = max(0.,a4(2,i,2))
      end do
    else if (iv == (-1)) then
      do i = i1, i2
        if (a4(2,i,1)*a4(1,i,1) <= 0.) then
          a4(2,i,1) = 0.
        endif
      end do
    else if (abs(iv) == 2) then
      do i = i1, i2
        a4(2,i,1) = a4(1,i,1)
        a4(3,i,1) = a4(1,i,1)
      end do
    endif
    do i = i1, i2
      d1 = delp(i,km)
      d2 = delp(i,km1)
      qm = (d2*a4(1,i,km)+d1*a4(1,i,km1))/(d1+d2)
      dq = 2.*(a4(1,i,km1)-a4(1,i,km))/(d1+d2)
      c1 = (a4(2,i,km1)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
      c3 = dq-2.0*c1*(d2*(5.*d1+d2)-3.*d1*d1)
      a4(2,i,km) = qm-c1*d1*d2*(d2+3.*d1)
      a4(3,i,km) = d1*(8.*c1*d1**2-c3)+a4(2,i,km)
      a4(2,i,km) = max(a4(2,i,km),min(a4(1,i,km),a4(1,i,km1)))
      a4(2,i,km) = min(a4(2,i,km),max(a4(1,i,km),a4(1,i,km1)))
      dc(i,km) = 0.5*(a4(1,i,km)-a4(2,i,km))
    end do
    if (iv == 0) then
      do i = i1, i2
        a4(2,i,km) = max(0.,a4(2,i,km))
        a4(3,i,km) = max(0.,a4(3,i,km))
      end do
    else if (iv < 0) then
      do i = i1, i2
        if (a4(1,i,km)*a4(3,i,km) <= 0.) then
          a4(3,i,km) = 0.
        endif
      end do
    endif
    do ka1 = 1, km1
      do i = i1, i2
        a4(3,i,ka1) = a4(2,i,ka1+1)
      end do
    end do
    do ka1 = 1, 2
      do i = i1, i2
        a4(4,i,ka1) = 3.*(2.*a4(1,i,ka1)-(a4(2,i,ka1)+a4(3,i,ka1)))
      end do
      call ppm_limiters( dc(i1,ka1),a4(1,i1,ka1),it,0 )
    end do
    if (kord >= 7) then
      do ka1 = 2, km1
        do i = i1, i2
          h2(i,ka1) = 2.*(dc(i,ka1+1)/delp(i,ka1+1)-dc(i,ka1-1)/delp(i,ka1-1))/(delp(i,ka1)+0.5*(delp(i,ka1-1)+delp(i,ka1+1)))*delp(i,ka1)**2
        end do
      end do
      fac = 1.5
      do ka1 = 3, km-2
        do i = i1, i2
          pmp = 2.*dc(i,ka1)
          qmp = a4(1,i,ka1)+pmp
          lac = a4(1,i,ka1)+fac*h2(i,ka1-1)+dc(i,ka1)
          a4(3,i,ka1) = min(max(a4(3,i,ka1),min(a4(1,i,ka1),qmp,lac)),max(a4(1,i,ka1),qmp,lac))
          qmp = a4(1,i,ka1)-pmp
          lac = a4(1,i,ka1)+fac*h2(i,ka1+1)-dc(i,ka1)
          a4(2,i,ka1) = min(max(a4(2,i,ka1),min(a4(1,i,ka1),qmp,lac)),max(a4(1,i,ka1),qmp,lac))
          a4(4,i,ka1) = 3.*(2.*a4(1,i,ka1)-(a4(2,i,ka1)+a4(3,i,ka1)))
        end do
        if (iv == 0 .and. kord >= 6) then
          call ppm_limiters( dc(i1,ka1),a4(1,i1,ka1),it,2 )
        endif
      end do
    else
      lmt = kord-3
      lmt = max(0,lmt)
      if (iv == 0) then
        lmt = min(2,lmt)
      endif
      do ka1 = 3, km-2
        if (kord /= 4) then
          do i = i1, i2
            a4(4,i,ka1) = 3.*(2.*a4(1,i,ka1)-(a4(2,i,ka1)+a4(3,i,ka1)))
          end do
        endif
        if (kord /= 6) then
          call ppm_limiters( dc(i1,ka1),a4(1,i1,ka1),it,lmt )
        endif
      end do
    endif
    do k1 = km1, k-1
      do i = i1, i2
        a4(4,i,k1) = 3.*(2.*a4(1,i,k1)-(a4(2,i,k1)+a4(3,i,k1)))
      end do
      call ppm_limiters( dc(i1,k1),a4(1,i1,k1),it,0 )
    end do
!$taf INCOMPLETE a4
    do i = i1, i2
      a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
    end do
    call ppm_limiters_ad( dc(i1,k),dc_ad(i1,k),a4(1,i1,k),a4_ad(1,i1,k),it,0 )
    do i = i1, i2
      a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
      a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
      a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
      a4_ad(4,i,k) = 0.
    end do
  end do
  a4 = a4h(:,:,:)
  do k = 2, km1
    do i = i1, i2
      c1 = (delp(i,k-1)+0.5*delp(i,k))/d4(i,k+1)
      c2 = (delp(i,k+1)+0.5*delp(i,k))/d4(i,k)
      df2(i,k) = delp(i,k)*(c1*delq(i,k)+c2*delq(i,k-1))/(d4(i,k)+delp(i,k+1))
      dc(i,k) = sign(min(abs(df2(i,k)),max(a4(1,i,k-1),a4(1,i,k),a4(1,i,k+1))-a4(1,i,k),a4(1,i,k)-min(a4(1,i,k-1),a4(1,i,k),a4(1,i,k+1))),df2(i,k))
    end do
  end do
  do k = 3, km1
    do i = i1, i2
      c1 = delq(i,k-1)*delp(i,k-1)/d4(i,k)
      a1 = d4(i,k-1)/(d4(i,k)+delp(i,k-1))
      a2 = d4(i,k+1)/(d4(i,k)+delp(i,k))
      a4(2,i,k) = a4(1,i,k-1)+c1+2./(d4(i,k-1)+d4(i,k+1))*(delp(i,k)*(c1*(a1-a2)+a2*dc(i,k-1))-delp(i,k-1)*a1*dc(i,k))
    end do
  end do
  do i = i1, i2
    d1 = delp(i,1)
    d2 = delp(i,2)
    qm = (d2*a4(1,i,1)+d1*a4(1,i,2))/(d1+d2)
    dq = 2.*(a4(1,i,2)-a4(1,i,1))/(d1+d2)
    c1 = 4.*(a4(2,i,3)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
    c3 = dq-0.5*c1*(d2*(5.*d1+d2)-3.*d1*d1)
    a4(2,i,2) = qm-0.25*c1*d1*d2*(d2+3.*d1)
    a4(2,i,1) = d1*(2.*c1*d1**2-c3)+a4(2,i,2)
    a4(2,i,2) = max(a4(2,i,2),min(a4(1,i,1),a4(1,i,2)))
    a4(2,i,2) = min(a4(2,i,2),max(a4(1,i,1),a4(1,i,2)))
    dc(i,1) = 0.5*(a4(2,i,2)-a4(1,i,1))
  end do
  if (iv == 0) then
    do i = i1, i2
      a4(2,i,1) = max(0.,a4(2,i,1))
      a4(2,i,2) = max(0.,a4(2,i,2))
    end do
  else if (iv == (-1)) then
    do i = i1, i2
      if (a4(2,i,1)*a4(1,i,1) <= 0.) then
        a4(2,i,1) = 0.
      endif
    end do
  else if (abs(iv) == 2) then
    do i = i1, i2
      a4(2,i,1) = a4(1,i,1)
      a4(3,i,1) = a4(1,i,1)
    end do
  endif
  do i = i1, i2
    d1 = delp(i,km)
    d2 = delp(i,km1)
    qm = (d2*a4(1,i,km)+d1*a4(1,i,km1))/(d1+d2)
    dq = 2.*(a4(1,i,km1)-a4(1,i,km))/(d1+d2)
    c1 = (a4(2,i,km1)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
    c3 = dq-2.0*c1*(d2*(5.*d1+d2)-3.*d1*d1)
    a4(2,i,km) = qm-c1*d1*d2*(d2+3.*d1)
    a4(3,i,km) = d1*(8.*c1*d1**2-c3)+a4(2,i,km)
    a4(2,i,km) = max(a4(2,i,km),min(a4(1,i,km),a4(1,i,km1)))
    a4(2,i,km) = min(a4(2,i,km),max(a4(1,i,km),a4(1,i,km1)))
    dc(i,km) = 0.5*(a4(1,i,km)-a4(2,i,km))
  end do
  if (iv == 0) then
    do i = i1, i2
      a4(2,i,km) = max(0.,a4(2,i,km))
      a4(3,i,km) = max(0.,a4(3,i,km))
    end do
  else if (iv < 0) then
    do i = i1, i2
      if (a4(1,i,km)*a4(3,i,km) <= 0.) then
        a4(3,i,km) = 0.
      endif
    end do
  endif
  do k = 1, km1
    do i = i1, i2
      a4(3,i,k) = a4(2,i,k+1)
    end do
  end do
  do k = 1, 2
    do i = i1, i2
      a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
    end do
    call ppm_limiters( dc(i1,k),a4(1,i1,k),it,0 )
  end do
!$taf INCOMPLETE h2
  if (kord >= 7) then
!$taf INCOMPLETE h2
    do k = 2, km1
      do i = i1, i2
        h2(i,k) = 2.*(dc(i,k+1)/delp(i,k+1)-dc(i,k-1)/delp(i,k-1))/(delp(i,k)+0.5*(delp(i,k-1)+delp(i,k+1)))*delp(i,k)**2
      end do
    end do
    fac = 1.5
    do k = km-2, 3, -1
      a4 = a4h(:,:,:)
      do ka3 = 2, km1
        do i = i1, i2
          c1 = (delp(i,ka3-1)+0.5*delp(i,ka3))/d4(i,ka3+1)
          c2 = (delp(i,ka3+1)+0.5*delp(i,ka3))/d4(i,ka3)
          df2(i,ka3) = delp(i,ka3)*(c1*delq(i,ka3)+c2*delq(i,ka3-1))/(d4(i,ka3)+delp(i,ka3+1))
          dc(i,ka3) = sign(min(abs(df2(i,ka3)),max(a4(1,i,ka3-1),a4(1,i,ka3),a4(1,i,ka3+1))-a4(1,i,ka3),a4(1,i,ka3)-min(a4(1,i,ka3-1),a4(1,i,ka3),a4(1,i,ka3+1))),df2(i,ka3))
        end do
      end do
      do ka3 = 3, km1
        do i = i1, i2
          c1 = delq(i,ka3-1)*delp(i,ka3-1)/d4(i,ka3)
          a1 = d4(i,ka3-1)/(d4(i,ka3)+delp(i,ka3-1))
          a2 = d4(i,ka3+1)/(d4(i,ka3)+delp(i,ka3))
          a4(2,i,ka3) = a4(1,i,ka3-1)+c1+2./(d4(i,ka3-1)+d4(i,ka3+1))*(delp(i,ka3)*(c1*(a1-a2)+a2*dc(i,ka3-1))-delp(i,ka3-1)*a1*dc(i,ka3))
        end do
      end do
      do i = i1, i2
        d1 = delp(i,1)
        d2 = delp(i,2)
        qm = (d2*a4(1,i,1)+d1*a4(1,i,2))/(d1+d2)
        dq = 2.*(a4(1,i,2)-a4(1,i,1))/(d1+d2)
        c1 = 4.*(a4(2,i,3)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
        c3 = dq-0.5*c1*(d2*(5.*d1+d2)-3.*d1*d1)
        a4(2,i,2) = qm-0.25*c1*d1*d2*(d2+3.*d1)
        a4(2,i,1) = d1*(2.*c1*d1**2-c3)+a4(2,i,2)
        a4(2,i,2) = max(a4(2,i,2),min(a4(1,i,1),a4(1,i,2)))
        a4(2,i,2) = min(a4(2,i,2),max(a4(1,i,1),a4(1,i,2)))
        dc(i,1) = 0.5*(a4(2,i,2)-a4(1,i,1))
      end do
      if (iv == 0) then
        do i = i1, i2
          a4(2,i,1) = max(0.,a4(2,i,1))
          a4(2,i,2) = max(0.,a4(2,i,2))
        end do
      else if (iv == (-1)) then
        do i = i1, i2
          if (a4(2,i,1)*a4(1,i,1) <= 0.) then
            a4(2,i,1) = 0.
          endif
        end do
      else if (abs(iv) == 2) then
        do i = i1, i2
          a4(2,i,1) = a4(1,i,1)
          a4(3,i,1) = a4(1,i,1)
        end do
      endif
      do i = i1, i2
        d1 = delp(i,km)
        d2 = delp(i,km1)
        qm = (d2*a4(1,i,km)+d1*a4(1,i,km1))/(d1+d2)
        dq = 2.*(a4(1,i,km1)-a4(1,i,km))/(d1+d2)
        c1 = (a4(2,i,km1)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
        c3 = dq-2.0*c1*(d2*(5.*d1+d2)-3.*d1*d1)
        a4(2,i,km) = qm-c1*d1*d2*(d2+3.*d1)
        a4(3,i,km) = d1*(8.*c1*d1**2-c3)+a4(2,i,km)
        a4(2,i,km) = max(a4(2,i,km),min(a4(1,i,km),a4(1,i,km1)))
        a4(2,i,km) = min(a4(2,i,km),max(a4(1,i,km),a4(1,i,km1)))
        dc(i,km) = 0.5*(a4(1,i,km)-a4(2,i,km))
      end do
      if (iv == 0) then
        do i = i1, i2
          a4(2,i,km) = max(0.,a4(2,i,km))
          a4(3,i,km) = max(0.,a4(3,i,km))
        end do
      else if (iv < 0) then
        do i = i1, i2
          if (a4(1,i,km)*a4(3,i,km) <= 0.) then
            a4(3,i,km) = 0.
          endif
        end do
      endif
      do ka3 = 1, km1
        do i = i1, i2
          a4(3,i,ka3) = a4(2,i,ka3+1)
        end do
      end do
      do ka3 = 1, 2
        do i = i1, i2
          a4(4,i,ka3) = 3.*(2.*a4(1,i,ka3)-(a4(2,i,ka3)+a4(3,i,ka3)))
        end do
        call ppm_limiters( dc(i1,ka3),a4(1,i1,ka3),it,0 )
      end do
      do k3 = 3, k-1
        do i = i1, i2
          pmp = 2.*dc(i,k3)
          qmp = a4(1,i,k3)+pmp
          lac = a4(1,i,k3)+fac*h2(i,k3-1)+dc(i,k3)
          a4(3,i,k3) = min(max(a4(3,i,k3),min(a4(1,i,k3),qmp,lac)),max(a4(1,i,k3),qmp,lac))
          qmp = a4(1,i,k3)-pmp
          lac = a4(1,i,k3)+fac*h2(i,k3+1)-dc(i,k3)
          a4(2,i,k3) = min(max(a4(2,i,k3),min(a4(1,i,k3),qmp,lac)),max(a4(1,i,k3),qmp,lac))
          a4(4,i,k3) = 3.*(2.*a4(1,i,k3)-(a4(2,i,k3)+a4(3,i,k3)))
        end do
        if (iv == 0 .and. kord >= 6) then
          call ppm_limiters( dc(i1,k3),a4(1,i1,k3),it,2 )
        endif
      end do
      a4s(:,:,:) = a4
!$taf INCOMPLETE a4
      do i = i1, i2
        pmp = 2.*dc(i,k)
        qmp = a4(1,i,k)+pmp
        lac = a4(1,i,k)+fac*h2(i,k-1)+dc(i,k)
        a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),qmp,lac)),max(a4(1,i,k),qmp,lac))
        qmp = a4(1,i,k)-pmp
        lac = a4(1,i,k)+fac*h2(i,k+1)-dc(i,k)
        a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),qmp,lac)),max(a4(1,i,k),qmp,lac))
        a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
      end do
      if (iv == 0 .and. kord >= 6) then
        call ppm_limiters_ad( dc(i1,k),dc_ad(i1,k),a4(1,i1,k),a4_ad(1,i1,k),it,2 )
      endif
      a4 = a4s(:,:,:)
      do i = i1, i2
        lac_ad = 0.
        pmp_ad = 0.
        qmp_ad = 0.
!$taf INCOMPLETE a4
        pmp = 2.*dc(i,k)
        qmp = a4(1,i,k)+pmp
        lac = a4(1,i,k)+fac*h2(i,k-1)+dc(i,k)
        a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),qmp,lac)),max(a4(1,i,k),qmp,lac))
        qmp = a4(1,i,k)-pmp
        lac = a4(1,i,k)+fac*h2(i,k+1)-dc(i,k)
        a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
        a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
        a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
        a4_ad(4,i,k) = 0.
        a4i = min(a4(1,i,k),qmp)
        a4j = min(a4i,lac)
        a4k = max(a4(2,i,k),a4j)
        a4l = max(a4(1,i,k),qmp)
        a4m = max(a4l,lac)
        a4j_ad = 0.
        a4k_ad = a4_ad(2,i,k)*(0.5+sign(0.5,a4m-a4k))
        a4m_ad = a4_ad(2,i,k)*(0.5-sign(0.5,a4m-a4k))
        a4l_ad = a4m_ad*(0.5+sign(0.5,a4l-lac))
        lac_ad = lac_ad+a4m_ad*(0.5-sign(0.5,a4l-lac))
        a4_ad(1,i,k) = a4_ad(1,i,k)+a4l_ad*(0.5+sign(0.5,a4(1,i,k)-qmp))
        qmp_ad = qmp_ad+a4l_ad*(0.5-sign(0.5,a4(1,i,k)-qmp))
        a4_ad(2,i,k) = a4k_ad*(0.5+sign(0.5,a4(2,i,k)-a4j))
        a4j_ad = a4k_ad*(0.5-sign(0.5,a4(2,i,k)-a4j))
        a4i_ad = a4j_ad*(0.5+sign(0.5,lac-a4i))
        lac_ad = lac_ad+a4j_ad*(0.5-sign(0.5,lac-a4i))
        a4_ad(1,i,k) = a4_ad(1,i,k)+a4i_ad*(0.5+sign(0.5,qmp-a4(1,i,k)))
        qmp_ad = qmp_ad+a4i_ad*(0.5-sign(0.5,qmp-a4(1,i,k)))
        a4_ad(1,i,k) = a4_ad(1,i,k)+lac_ad
        dc_ad(i,k) = dc_ad(i,k)-lac_ad
        h2_ad(i,k+1) = h2_ad(i,k+1)+lac_ad*fac
        lac_ad = 0.
        a4_ad(1,i,k) = a4_ad(1,i,k)+qmp_ad
        pmp_ad = pmp_ad-qmp_ad
        qmp_ad = 0.
        a4 = a4s(:,:,:)
        qmp = a4(1,i,k)+pmp
        lac = a4(1,i,k)+fac*h2(i,k-1)+dc(i,k)
        a4n = min(a4(1,i,k),qmp)
        a4o = min(a4n,lac)
        a4p = max(a4(3,i,k),a4o)
        a4q = max(a4(1,i,k),qmp)
        a4r = max(a4q,lac)
        a4o_ad = 0.
        a4p_ad = a4_ad(3,i,k)*(0.5+sign(0.5,a4r-a4p))
        a4r_ad = a4_ad(3,i,k)*(0.5-sign(0.5,a4r-a4p))
        a4q_ad = a4r_ad*(0.5+sign(0.5,a4q-lac))
        lac_ad = lac_ad+a4r_ad*(0.5-sign(0.5,a4q-lac))
        a4_ad(1,i,k) = a4_ad(1,i,k)+a4q_ad*(0.5+sign(0.5,a4(1,i,k)-qmp))
        qmp_ad = qmp_ad+a4q_ad*(0.5-sign(0.5,a4(1,i,k)-qmp))
        a4_ad(3,i,k) = a4p_ad*(0.5+sign(0.5,a4(3,i,k)-a4o))
        a4o_ad = a4p_ad*(0.5-sign(0.5,a4(3,i,k)-a4o))
        a4n_ad = a4o_ad*(0.5+sign(0.5,lac-a4n))
        lac_ad = lac_ad+a4o_ad*(0.5-sign(0.5,lac-a4n))
        a4_ad(1,i,k) = a4_ad(1,i,k)+a4n_ad*(0.5+sign(0.5,qmp-a4(1,i,k)))
        qmp_ad = qmp_ad+a4n_ad*(0.5-sign(0.5,qmp-a4(1,i,k)))
        a4_ad(1,i,k) = a4_ad(1,i,k)+lac_ad
        dc_ad(i,k) = dc_ad(i,k)+lac_ad
        h2_ad(i,k-1) = h2_ad(i,k-1)+lac_ad*fac
        lac_ad = 0.
        a4_ad(1,i,k) = a4_ad(1,i,k)+qmp_ad
        pmp_ad = pmp_ad+qmp_ad
        qmp_ad = 0.
        dc_ad(i,k) = dc_ad(i,k)+2*pmp_ad
        pmp_ad = 0.
      end do
    end do
    do k = 2, km1
      do i = i1, i2
        dc_ad(i,k-1) = dc_ad(i,k-1)-h2_ad(i,k)*(2.*(1/delp(i,k-1))/(delp(i,k)+0.5*(delp(i,k-1)+delp(i,k+1))))*delp(i,k)**2
        dc_ad(i,k+1) = dc_ad(i,k+1)+h2_ad(i,k)*(2.*(1/delp(i,k+1))/(delp(i,k)+0.5*(delp(i,k-1)+delp(i,k+1))))*delp(i,k)**2
        h2_ad(i,k) = 0.
      end do
    end do
  else
    lmt = kord-3
    lmt = max(0,lmt)
    if (iv == 0) then
      lmt = min(2,lmt)
    endif
    do k = km-2, 3, -1
      a4 = a4h(:,:,:)
      do ka2 = 2, km1
        do i = i1, i2
          c1 = (delp(i,ka2-1)+0.5*delp(i,ka2))/d4(i,ka2+1)
          c2 = (delp(i,ka2+1)+0.5*delp(i,ka2))/d4(i,ka2)
          df2(i,ka2) = delp(i,ka2)*(c1*delq(i,ka2)+c2*delq(i,ka2-1))/(d4(i,ka2)+delp(i,ka2+1))
          dc(i,ka2) = sign(min(abs(df2(i,ka2)),max(a4(1,i,ka2-1),a4(1,i,ka2),a4(1,i,ka2+1))-a4(1,i,ka2),a4(1,i,ka2)-min(a4(1,i,ka2-1),a4(1,i,ka2),a4(1,i,ka2+1))),df2(i,ka2))
        end do
      end do
      do ka2 = 3, km1
        do i = i1, i2
          c1 = delq(i,ka2-1)*delp(i,ka2-1)/d4(i,ka2)
          a1 = d4(i,ka2-1)/(d4(i,ka2)+delp(i,ka2-1))
          a2 = d4(i,ka2+1)/(d4(i,ka2)+delp(i,ka2))
          a4(2,i,ka2) = a4(1,i,ka2-1)+c1+2./(d4(i,ka2-1)+d4(i,ka2+1))*(delp(i,ka2)*(c1*(a1-a2)+a2*dc(i,ka2-1))-delp(i,ka2-1)*a1*dc(i,ka2))
        end do
      end do
      do i = i1, i2
        d1 = delp(i,1)
        d2 = delp(i,2)
        qm = (d2*a4(1,i,1)+d1*a4(1,i,2))/(d1+d2)
        dq = 2.*(a4(1,i,2)-a4(1,i,1))/(d1+d2)
        c1 = 4.*(a4(2,i,3)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
        c3 = dq-0.5*c1*(d2*(5.*d1+d2)-3.*d1*d1)
        a4(2,i,2) = qm-0.25*c1*d1*d2*(d2+3.*d1)
        a4(2,i,1) = d1*(2.*c1*d1**2-c3)+a4(2,i,2)
        a4(2,i,2) = max(a4(2,i,2),min(a4(1,i,1),a4(1,i,2)))
        a4(2,i,2) = min(a4(2,i,2),max(a4(1,i,1),a4(1,i,2)))
        dc(i,1) = 0.5*(a4(2,i,2)-a4(1,i,1))
      end do
      if (iv == 0) then
        do i = i1, i2
          a4(2,i,1) = max(0.,a4(2,i,1))
          a4(2,i,2) = max(0.,a4(2,i,2))
        end do
      else if (iv == (-1)) then
        do i = i1, i2
          if (a4(2,i,1)*a4(1,i,1) <= 0.) then
            a4(2,i,1) = 0.
          endif
        end do
      else if (abs(iv) == 2) then
        do i = i1, i2
          a4(2,i,1) = a4(1,i,1)
          a4(3,i,1) = a4(1,i,1)
        end do
      endif
      do i = i1, i2
        d1 = delp(i,km)
        d2 = delp(i,km1)
        qm = (d2*a4(1,i,km)+d1*a4(1,i,km1))/(d1+d2)
        dq = 2.*(a4(1,i,km1)-a4(1,i,km))/(d1+d2)
        c1 = (a4(2,i,km1)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
        c3 = dq-2.0*c1*(d2*(5.*d1+d2)-3.*d1*d1)
        a4(2,i,km) = qm-c1*d1*d2*(d2+3.*d1)
        a4(3,i,km) = d1*(8.*c1*d1**2-c3)+a4(2,i,km)
        a4(2,i,km) = max(a4(2,i,km),min(a4(1,i,km),a4(1,i,km1)))
        a4(2,i,km) = min(a4(2,i,km),max(a4(1,i,km),a4(1,i,km1)))
        dc(i,km) = 0.5*(a4(1,i,km)-a4(2,i,km))
      end do
      if (iv == 0) then
        do i = i1, i2
          a4(2,i,km) = max(0.,a4(2,i,km))
          a4(3,i,km) = max(0.,a4(3,i,km))
        end do
      else if (iv < 0) then
        do i = i1, i2
          if (a4(1,i,km)*a4(3,i,km) <= 0.) then
            a4(3,i,km) = 0.
          endif
        end do
      endif
      do ka2 = 1, km1
        do i = i1, i2
          a4(3,i,ka2) = a4(2,i,ka2+1)
        end do
      end do
      do ka2 = 1, 2
        do i = i1, i2
          a4(4,i,ka2) = 3.*(2.*a4(1,i,ka2)-(a4(2,i,ka2)+a4(3,i,ka2)))
        end do
        call ppm_limiters( dc(i1,ka2),a4(1,i1,ka2),it,0 )
      end do
      do k2 = 3, k-1
        if (kord /= 4) then
          do i = i1, i2
            a4(4,i,k2) = 3.*(2.*a4(1,i,k2)-(a4(2,i,k2)+a4(3,i,k2)))
          end do
        endif
        if (kord /= 6) then
          call ppm_limiters( dc(i1,k2),a4(1,i1,k2),it,lmt )
        endif
      end do
!$taf INCOMPLETE a4
      if (kord /= 4) then
        do i = i1, i2
          a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
        end do
      endif
      if (kord /= 6) then
        call ppm_limiters_ad( dc(i1,k),dc_ad(i1,k),a4(1,i1,k),a4_ad(1,i1,k),it,lmt )
      endif
      if (kord /= 4) then
        do i = i1, i2
          a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
          a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
          a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
          a4_ad(4,i,k) = 0.
        end do
      endif
    end do
  endif
  a4 = a4h(:,:,:)
  do k = 2, km1
    do i = i1, i2
      c1 = (delp(i,k-1)+0.5*delp(i,k))/d4(i,k+1)
      c2 = (delp(i,k+1)+0.5*delp(i,k))/d4(i,k)
      df2(i,k) = delp(i,k)*(c1*delq(i,k)+c2*delq(i,k-1))/(d4(i,k)+delp(i,k+1))
      dc(i,k) = sign(min(abs(df2(i,k)),max(a4(1,i,k-1),a4(1,i,k),a4(1,i,k+1))-a4(1,i,k),a4(1,i,k)-min(a4(1,i,k-1),a4(1,i,k),a4(1,i,k+1))),df2(i,k))
    end do
  end do
  do k = 3, km1
    do i = i1, i2
      c1 = delq(i,k-1)*delp(i,k-1)/d4(i,k)
      a1 = d4(i,k-1)/(d4(i,k)+delp(i,k-1))
      a2 = d4(i,k+1)/(d4(i,k)+delp(i,k))
      a4(2,i,k) = a4(1,i,k-1)+c1+2./(d4(i,k-1)+d4(i,k+1))*(delp(i,k)*(c1*(a1-a2)+a2*dc(i,k-1))-delp(i,k-1)*a1*dc(i,k))
    end do
  end do
  do i = i1, i2
    d1 = delp(i,1)
    d2 = delp(i,2)
    qm = (d2*a4(1,i,1)+d1*a4(1,i,2))/(d1+d2)
    dq = 2.*(a4(1,i,2)-a4(1,i,1))/(d1+d2)
    c1 = 4.*(a4(2,i,3)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
    c3 = dq-0.5*c1*(d2*(5.*d1+d2)-3.*d1*d1)
    a4(2,i,2) = qm-0.25*c1*d1*d2*(d2+3.*d1)
    a4(2,i,1) = d1*(2.*c1*d1**2-c3)+a4(2,i,2)
    a4(2,i,2) = max(a4(2,i,2),min(a4(1,i,1),a4(1,i,2)))
    a4(2,i,2) = min(a4(2,i,2),max(a4(1,i,1),a4(1,i,2)))
    dc(i,1) = 0.5*(a4(2,i,2)-a4(1,i,1))
  end do
  if (iv == 0) then
    do i = i1, i2
      a4(2,i,1) = max(0.,a4(2,i,1))
      a4(2,i,2) = max(0.,a4(2,i,2))
    end do
  else if (iv == (-1)) then
    do i = i1, i2
      if (a4(2,i,1)*a4(1,i,1) <= 0.) then
        a4(2,i,1) = 0.
      endif
    end do
  else if (abs(iv) == 2) then
    do i = i1, i2
      a4(2,i,1) = a4(1,i,1)
      a4(3,i,1) = a4(1,i,1)
    end do
  endif
  do i = i1, i2
    d1 = delp(i,km)
    d2 = delp(i,km1)
    qm = (d2*a4(1,i,km)+d1*a4(1,i,km1))/(d1+d2)
    dq = 2.*(a4(1,i,km1)-a4(1,i,km))/(d1+d2)
    c1 = (a4(2,i,km1)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
    c3 = dq-2.0*c1*(d2*(5.*d1+d2)-3.*d1*d1)
    a4(2,i,km) = qm-c1*d1*d2*(d2+3.*d1)
    a4(3,i,km) = d1*(8.*c1*d1**2-c3)+a4(2,i,km)
    a4(2,i,km) = max(a4(2,i,km),min(a4(1,i,km),a4(1,i,km1)))
    a4(2,i,km) = min(a4(2,i,km),max(a4(1,i,km),a4(1,i,km1)))
    dc(i,km) = 0.5*(a4(1,i,km)-a4(2,i,km))
  end do
  if (iv == 0) then
    do i = i1, i2
      a4(2,i,km) = max(0.,a4(2,i,km))
      a4(3,i,km) = max(0.,a4(3,i,km))
    end do
  else if (iv < 0) then
    do i = i1, i2
      if (a4(1,i,km)*a4(3,i,km) <= 0.) then
        a4(3,i,km) = 0.
      endif
    end do
  endif
  do k = 1, km1
    do i = i1, i2
      a4(3,i,k) = a4(2,i,k+1)
    end do
  end do
  do k = 2, 1, -1
    a4 = a4h(:,:,:)
    do ka4 = 2, km1
      do i = i1, i2
        c1 = (delp(i,ka4-1)+0.5*delp(i,ka4))/d4(i,ka4+1)
        c2 = (delp(i,ka4+1)+0.5*delp(i,ka4))/d4(i,ka4)
        df2(i,ka4) = delp(i,ka4)*(c1*delq(i,ka4)+c2*delq(i,ka4-1))/(d4(i,ka4)+delp(i,ka4+1))
        dc(i,ka4) = sign(min(abs(df2(i,ka4)),max(a4(1,i,ka4-1),a4(1,i,ka4),a4(1,i,ka4+1))-a4(1,i,ka4),a4(1,i,ka4)-min(a4(1,i,ka4-1),a4(1,i,ka4),a4(1,i,ka4+1))),df2(i,ka4))
      end do
    end do
    do ka4 = 3, km1
      do i = i1, i2
        c1 = delq(i,ka4-1)*delp(i,ka4-1)/d4(i,ka4)
        a1 = d4(i,ka4-1)/(d4(i,ka4)+delp(i,ka4-1))
        a2 = d4(i,ka4+1)/(d4(i,ka4)+delp(i,ka4))
        a4(2,i,ka4) = a4(1,i,ka4-1)+c1+2./(d4(i,ka4-1)+d4(i,ka4+1))*(delp(i,ka4)*(c1*(a1-a2)+a2*dc(i,ka4-1))-delp(i,ka4-1)*a1*dc(i,ka4))
      end do
    end do
    do i = i1, i2
      d1 = delp(i,1)
      d2 = delp(i,2)
      qm = (d2*a4(1,i,1)+d1*a4(1,i,2))/(d1+d2)
      dq = 2.*(a4(1,i,2)-a4(1,i,1))/(d1+d2)
      c1 = 4.*(a4(2,i,3)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
      c3 = dq-0.5*c1*(d2*(5.*d1+d2)-3.*d1*d1)
      a4(2,i,2) = qm-0.25*c1*d1*d2*(d2+3.*d1)
      a4(2,i,1) = d1*(2.*c1*d1**2-c3)+a4(2,i,2)
      a4(2,i,2) = max(a4(2,i,2),min(a4(1,i,1),a4(1,i,2)))
      a4(2,i,2) = min(a4(2,i,2),max(a4(1,i,1),a4(1,i,2)))
    end do
    if (iv == 0) then
      do i = i1, i2
        a4(2,i,1) = max(0.,a4(2,i,1))
        a4(2,i,2) = max(0.,a4(2,i,2))
      end do
    else if (iv == (-1)) then
      do i = i1, i2
        if (a4(2,i,1)*a4(1,i,1) <= 0.) then
          a4(2,i,1) = 0.
        endif
      end do
    else if (abs(iv) == 2) then
      do i = i1, i2
        a4(2,i,1) = a4(1,i,1)
        a4(3,i,1) = a4(1,i,1)
      end do
    endif
    do i = i1, i2
      d1 = delp(i,km)
      d2 = delp(i,km1)
      qm = (d2*a4(1,i,km)+d1*a4(1,i,km1))/(d1+d2)
      dq = 2.*(a4(1,i,km1)-a4(1,i,km))/(d1+d2)
      c1 = (a4(2,i,km1)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
      c3 = dq-2.0*c1*(d2*(5.*d1+d2)-3.*d1*d1)
      a4(2,i,km) = qm-c1*d1*d2*(d2+3.*d1)
      a4(3,i,km) = d1*(8.*c1*d1**2-c3)+a4(2,i,km)
      a4(2,i,km) = max(a4(2,i,km),min(a4(1,i,km),a4(1,i,km1)))
      a4(2,i,km) = min(a4(2,i,km),max(a4(1,i,km),a4(1,i,km1)))
    end do
    if (iv == 0) then
      do i = i1, i2
        a4(2,i,km) = max(0.,a4(2,i,km))
        a4(3,i,km) = max(0.,a4(3,i,km))
      end do
    else if (iv < 0) then
      do i = i1, i2
        if (a4(1,i,km)*a4(3,i,km) <= 0.) then
          a4(3,i,km) = 0.
        endif
      end do
    endif
    do ka4 = 1, km1
      do i = i1, i2
        a4(3,i,ka4) = a4(2,i,ka4+1)
      end do
    end do
    do k4 = 1, k-1
      do i = i1, i2
        a4(4,i,k4) = 3.*(2.*a4(1,i,k4)-(a4(2,i,k4)+a4(3,i,k4)))
      end do
      call ppm_limiters( dc(i1,k4),a4(1,i1,k4),it,0 )
    end do
!$taf INCOMPLETE a4
    do i = i1, i2
      a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
    end do
    call ppm_limiters_ad( dc(i1,k),dc_ad(i1,k),a4(1,i1,k),a4_ad(1,i1,k),it,0 )
    do i = i1, i2
      a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
      a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
      a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
      a4_ad(4,i,k) = 0.
    end do
  end do
  do k = 1, km1
    do i = i1, i2
      a4_ad(2,i,k+1) = a4_ad(2,i,k+1)+a4_ad(3,i,k)
      a4_ad(3,i,k) = 0.
    end do
  end do
  a4 = a4h(:,:,:)
  do k = 2, km1
    do i = i1, i2
      c1 = (delp(i,k-1)+0.5*delp(i,k))/d4(i,k+1)
      c2 = (delp(i,k+1)+0.5*delp(i,k))/d4(i,k)
      df2(i,k) = delp(i,k)*(c1*delq(i,k)+c2*delq(i,k-1))/(d4(i,k)+delp(i,k+1))
      dc(i,k) = sign(min(abs(df2(i,k)),max(a4(1,i,k-1),a4(1,i,k),a4(1,i,k+1))-a4(1,i,k),a4(1,i,k)-min(a4(1,i,k-1),a4(1,i,k),a4(1,i,k+1))),df2(i,k))
    end do
  end do
  do k = 3, km1
    do i = i1, i2
      c1 = delq(i,k-1)*delp(i,k-1)/d4(i,k)
      a1 = d4(i,k-1)/(d4(i,k)+delp(i,k-1))
      a2 = d4(i,k+1)/(d4(i,k)+delp(i,k))
      a4(2,i,k) = a4(1,i,k-1)+c1+2./(d4(i,k-1)+d4(i,k+1))*(delp(i,k)*(c1*(a1-a2)+a2*dc(i,k-1))-delp(i,k-1)*a1*dc(i,k))
    end do
  end do
  do i = i1, i2
    d1 = delp(i,1)
    d2 = delp(i,2)
    qm = (d2*a4(1,i,1)+d1*a4(1,i,2))/(d1+d2)
    dq = 2.*(a4(1,i,2)-a4(1,i,1))/(d1+d2)
    c1 = 4.*(a4(2,i,3)-qm-d2*dq)/(d2*(2.*d2*d2+d1*(d2+3.*d1)))
    c3 = dq-0.5*c1*(d2*(5.*d1+d2)-3.*d1*d1)
