  integer :: k1
  integer :: k2
  integer :: k3
  integer :: k4
  integer :: ka1
  integer :: ka2
  integer :: kb1
  integer :: kb2
  real :: lac_1
  real :: lac_1_ad
  real :: lac_2
  real :: lac_2_ad
  real :: pmp_1
  real :: pmp_1_ad
  real :: pmp_2
  real :: pmp_2_ad
  real :: q(i1:i2,km+1)
  real :: q_ad(i1:i2,km+1)
  real :: qh
  real :: qh_ad
  real :: qi
  real :: qi_ad
  real :: qj
  real :: qj_ad
  real :: qk
  real :: qk_ad
  real :: ql
  real :: ql_ad
  real :: qm
  real :: qm_ad
  real :: qn
  real :: qn_ad
  real :: qo
  real :: qo_ad
  real :: qp_ad
  real :: qq_ad
  real :: qr_ad
  real :: qt_ad
  real :: qu_ad
  real :: qv_ad
  real :: x0
  real :: x0_ad
  real :: x1
  real :: x1_ad
  real :: x1h_ad
  real :: x1i_ad

!----------------------------------------------
! SAVE REQUIRED INPUT VARIABLES
!----------------------------------------------
  a6i(:,:,:) = a4

!----------------------------------------------
! RESET LOCAL ADJOINT VARIABLES NO ALLOC
!----------------------------------------------
  gam_ad(:,:) = 0.
  lac_1_ad = 0.
  lac_2_ad = 0.
  pmp_1_ad = 0.
  pmp_2_ad = 0.
  q_ad(:,:) = 0.
  x0_ad = 0.
  x1_ad = 0.

!$taf INCOMPLETE a4,d4,ext5,ext6,extm,gam,q
  if (iv == (-2)) then
    do i = i1, i2
      gam(i,2) = 0.5
      q(i,1) = 1.5*a4(1,i,1)
    end do
    do k = 2, km-1
      do i = i1, i2
        grat = delp(i,k-1)/delp(i,k)
        bet = 2.+grat+grat-gam(i,k)
        q(i,k) = (3.*(a4(1,i,k-1)+a4(1,i,k))-q(i,k-1))/bet
        gam(i,k+1) = grat/bet
      end do
    end do
    do i = i1, i2
      grat = delp(i,km-1)/delp(i,km)
      q(i,km) = (3.*(a4(1,i,km-1)+a4(1,i,km))-grat*qs(i)-q(i,km-1))/(2.+grat+grat-gam(i,km))
      q(i,km+1) = qs(i)
    end do
    do k = km-1, 1, -1
      do i = i1, i2
        q(i,k) = q(i,k)-gam(i,k+1)*q(i,k+1)
      end do
    end do
  else
    do i = i1, i2
      grat = delp(i,2)/delp(i,1)
      bet = grat*(grat+0.5)
      q(i,1) = ((grat+grat)*(grat+1.)*a4(1,i,1)+a4(1,i,2))/bet
      gam(i,1) = (1.+grat*(grat+1.5))/bet
    end do
    do k = 2, km
      do i = i1, i2
        d4(i) = delp(i,k-1)/delp(i,k)
        bet = 2.+d4(i)+d4(i)-gam(i,k-1)
        q(i,k) = (3.*(a4(1,i,k-1)+d4(i)*a4(1,i,k))-q(i,k-1))/bet
        gam(i,k) = d4(i)/bet
      end do
    end do
    do i = i1, i2
      a_bot = 1.+d4(i)*(d4(i)+1.5)
      q(i,km+1) = (2.*d4(i)*(d4(i)+1.)*a4(1,i,km)+a4(1,i,km-1)-a_bot*q(i,km))/(d4(i)*(d4(i)+0.5)-a_bot*gam(i,km))
    end do
    do k = km, 1, -1
      do i = i1, i2
        q(i,k) = q(i,k)-gam(i,k)*q(i,k+1)
      end do
    end do
  endif
!$taf INCOMPLETE a4,ext5,ext6,extm,gam,q
  if (abs(kord) > 16) then
    do k = 1, km
      do i = i1, i2
        a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
        a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
        a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
        a4_ad(4,i,k) = 0.
        q_ad(i,k+1) = q_ad(i,k+1)+a4_ad(3,i,k)
        a4_ad(3,i,k) = 0.
        q_ad(i,k) = q_ad(i,k)+a4_ad(2,i,k)
        a4_ad(2,i,k) = 0.
      end do
    end do
  else
!$taf INCOMPLETE a4,ext5,ext6,extm,gam,q
    im = i2-i1+1
    do i = i1, i2
      q(i,2) = min(q(i,2),max(a4(1,i,1),a4(1,i,2)))
      q(i,2) = max(q(i,2),min(a4(1,i,1),a4(1,i,2)))
    end do
    do k = 2, km
      do i = i1, i2
        gam(i,k) = a4(1,i,k)-a4(1,i,k-1)
      end do
    end do
    do k = 3, km-1
      do i = i1, i2
        if (gam(i,k-1)*gam(i,k+1) > 0.) then
          q(i,k) = min(q(i,k),max(a4(1,i,k-1),a4(1,i,k)))
          q(i,k) = max(q(i,k),min(a4(1,i,k-1),a4(1,i,k)))
        else
          if (gam(i,k-1) > 0.) then
            q(i,k) = max(q(i,k),min(a4(1,i,k-1),a4(1,i,k)))
          else
            q(i,k) = min(q(i,k),max(a4(1,i,k-1),a4(1,i,k)))
            if (iv == 0) then
              q(i,k) = max(0.,q(i,k))
            endif
          endif
        endif
      end do
    end do
    do i = i1, i2
      q(i,km) = min(q(i,km),max(a4(1,i,km-1),a4(1,i,km)))
      q(i,km) = max(q(i,km),min(a4(1,i,km-1),a4(1,i,km)))
    end do
    do k = 1, km
      do i = i1, i2
        a4(2,i,k) = q(i,k)
        a4(3,i,k) = q(i,k+1)
      end do
    end do
    do k = 1, km
      if (k == 1 .or. k == km) then
        do i = i1, i2
          extm(i,k) = (a4(2,i,k)-a4(1,i,k))*(a4(3,i,k)-a4(1,i,k)) > 0.
        end do
      else
        do i = i1, i2
          extm(i,k) = gam(i,k)*gam(i,k+1) < 0.
        end do
      endif
      if (abs(kord) > 9) then
        do i = i1, i2
          x0 = 2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k))
          x1 = abs(a4(2,i,k)-a4(3,i,k))
          a4(4,i,k) = 3.*x0
          ext5(i,k) = abs(x0) > x1
          ext6(i,k) = abs(a4(4,i,k)) > x1
        end do
      endif
    end do
    if (iv == 0) then
      do i = i1, i2
        a4(2,i,1) = max(0.,a4(2,i,1))
      end do
    else if (iv == (-1)) then
      do i = i1, i2
        if (a4(2,i,1)*a4(1,i,1) <= 0.) then
          a4(2,i,1) = 0.
        endif
      end do
    else if (iv == 2) then
      do i = i1, i2
        a4(2,i,1) = a4(1,i,1)
        a4(3,i,1) = a4(1,i,1)
        a4(4,i,1) = 0.
      end do
    endif
    if (iv /= 2) then
      do i = i1, i2
        a4(4,i,1) = 3.*(2.*a4(1,i,1)-(a4(2,i,1)+a4(3,i,1)))
      end do
      call cs_limiters( im,extm(i1,1),a4(1,i1,1),1 )
    endif
    do i = i1, i2
      a4(4,i,2) = 3.*(2.*a4(1,i,2)-(a4(2,i,2)+a4(3,i,2)))
    end do
    call cs_limiters( im,extm(i1,2),a4(1,i1,2),2 )
    do k = 3, km-2
      if (abs(kord) < 9) then
        do i = i1, i2
          pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
          lac_1 = pmp_1+1.5*gam(i,k+2)
          a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
          pmp_2 = a4(1,i,k)+2.*gam(i,k)
          lac_2 = pmp_2-1.5*gam(i,k-1)
          a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),pmp_2,lac_2)),max(a4(1,i,k),pmp_2,lac_2))
          a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
        end do
      else if (abs(kord) == 9) then
        do i = i1, i2
          if (extm(i,k) .and. extm(i,k-1)) then
            a4(2,i,k) = a4(1,i,k)
            a4(3,i,k) = a4(1,i,k)
            a4(4,i,k) = 0.
          else if (extm(i,k) .and. extm(i,k+1)) then
            a4(2,i,k) = a4(1,i,k)
            a4(3,i,k) = a4(1,i,k)
            a4(4,i,k) = 0.
          else if (extm(i,k) .and. a4(1,i,k) < qmin) then
            a4(2,i,k) = a4(1,i,k)
            a4(3,i,k) = a4(1,i,k)
            a4(4,i,k) = 0.
          else
            a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
            if (abs(a4(4,i,k)) > abs(a4(2,i,k)-a4(3,i,k))) then
              pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
              lac_1 = pmp_1+1.5*gam(i,k+2)
              a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
              pmp_2 = a4(1,i,k)+2.*gam(i,k)
              lac_2 = pmp_2-1.5*gam(i,k-1)
              a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),pmp_2,lac_2)),max(a4(1,i,k),pmp_2,lac_2))
              a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
            endif
          endif
        end do
      else if (abs(kord) == 10) then
        do i = i1, i2
          if (ext5(i,k)) then
            if (ext5(i,k-1) .or. ext5(i,k+1)) then
              a4(2,i,k) = a4(1,i,k)
              a4(3,i,k) = a4(1,i,k)
            else if (ext6(i,k-1) .or. ext6(i,k+1)) then
              pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
              lac_1 = pmp_1+1.5*gam(i,k+2)
              a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
              pmp_2 = a4(1,i,k)+2.*gam(i,k)
              lac_2 = pmp_2-1.5*gam(i,k-1)
              a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),pmp_2,lac_2)),max(a4(1,i,k),pmp_2,lac_2))
            endif
          else if (ext6(i,k)) then
            if (ext5(i,k-1) .or. ext5(i,k+1)) then
              pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
              lac_1 = pmp_1+1.5*gam(i,k+2)
              a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
              pmp_2 = a4(1,i,k)+2.*gam(i,k)
              lac_2 = pmp_2-1.5*gam(i,k-1)
              a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),pmp_2,lac_2)),max(a4(1,i,k),pmp_2,lac_2))
            endif
          endif
        end do
        do i = i1, i2
          a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
        end do
      else if (abs(kord) == 12) then
        do i = i1, i2
          if (extm(i,k)) then
            a4(2,i,k) = a4(1,i,k)
            a4(3,i,k) = a4(1,i,k)
            a4(4,i,k) = 0.
          else
            a4(4,i,k) = 6.*a4(1,i,k)-3.*(a4(2,i,k)+a4(3,i,k))
            if (abs(a4(4,i,k)) > abs(a4(2,i,k)-a4(3,i,k))) then
              pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
              lac_1 = pmp_1+1.5*gam(i,k+2)
              a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
              pmp_2 = a4(1,i,k)+2.*gam(i,k)
              lac_2 = pmp_2-1.5*gam(i,k-1)
              a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),pmp_2,lac_2)),max(a4(1,i,k),pmp_2,lac_2))
              a4(4,i,k) = 6.*a4(1,i,k)-3.*(a4(2,i,k)+a4(3,i,k))
            endif
          endif
        end do
      else if (abs(kord) == 13) then
        do i = i1, i2
          if (ext6(i,k)) then
            if (ext6(i,k-1) .and. ext6(i,k+1)) then
              a4(2,i,k) = a4(1,i,k)
              a4(3,i,k) = a4(1,i,k)
            endif
          endif
        end do
        do i = i1, i2
          a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
        end do
      else if (abs(kord) == 14) then
        do i = i1, i2
          a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
        end do
      else if (abs(kord) == 15) then
        do i = i1, i2
          if (ext5(i,k) .and. ext5(i,k-1)) then
            a4(2,i,k) = a4(1,i,k)
            a4(3,i,k) = a4(1,i,k)
          else if (ext5(i,k) .and. ext5(i,k+1)) then
            a4(2,i,k) = a4(1,i,k)
            a4(3,i,k) = a4(1,i,k)
          else if (ext5(i,k) .and. a4(1,i,k) < qmin) then
            a4(2,i,k) = a4(1,i,k)
            a4(3,i,k) = a4(1,i,k)
          else if (ext6(i,k)) then
            pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
            lac_1 = pmp_1+1.5*gam(i,k+2)
            a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
            pmp_2 = a4(1,i,k)+2.*gam(i,k)
            lac_2 = pmp_2-1.5*gam(i,k-1)
            a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),pmp_2,lac_2)),max(a4(1,i,k),pmp_2,lac_2))
          endif
        end do
        do i = i1, i2
          a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
        end do
      else if (abs(kord) == 16) then
        do i = i1, i2
          if (ext5(i,k)) then
            if (ext5(i,k-1) .or. ext5(i,k+1)) then
              a4(2,i,k) = a4(1,i,k)
              a4(3,i,k) = a4(1,i,k)
            else if (ext6(i,k-1) .or. ext6(i,k+1)) then
              pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
              lac_1 = pmp_1+1.5*gam(i,k+2)
              a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
              pmp_2 = a4(1,i,k)+2.*gam(i,k)
              lac_2 = pmp_2-1.5*gam(i,k-1)
              a4(3,i,k) = min(max(a4(3,i,k),min(a4(1,i,k),pmp_2,lac_2)),max(a4(1,i,k),pmp_2,lac_2))
            endif
          endif
        end do
        do i = i1, i2
          a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
        end do
      else
        do i = i1, i2
          if (ext5(i,k) .and. (ext5(i,k-1) .or. ext5(i,k+1) .or. a4(1,i,k) < qmin)) then
            a4(2,i,k) = a4(1,i,k)
            a4(3,i,k) = a4(1,i,k)
            a4(4,i,k) = 0.
          else
            a4(4,i,k) = 3.*(2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k)))
          endif
        end do
      endif
      if (iv == 0) then
        call cs_limiters( im,extm(i1,k),a4(1,i1,k),0 )
      endif
    end do
    if (iv == 0) then
      do i = i1, i2
        a4(3,i,km) = max(0.,a4(3,i,km))
      end do
    else if (iv == (-1)) then
      do i = i1, i2
        if (a4(3,i,km)*a4(1,i,km) <= 0.) then
          a4(3,i,km) = 0.
        endif
      end do
    endif
    do k = km, km-1, -1
      do ka1 = 1, km
        do i = i1, i2
          a4(2,i,ka1) = q(i,ka1)
          a4(3,i,ka1) = q(i,ka1+1)
        end do
      end do
      do ka1 = 1, km
        if (abs(kord) > 9) then
          do i = i1, i2
            x0 = 2.*a4(1,i,ka1)-(a4(2,i,ka1)+a4(3,i,ka1))
            a4(4,i,ka1) = 3.*x0
          end do
        endif
      end do
      if (iv == 0) then
        do i = i1, i2
          a4(2,i,1) = max(0.,a4(2,i,1))
        end do
      else if (iv == (-1)) then
        do i = i1, i2
          if (a4(2,i,1)*a4(1,i,1) <= 0.) then
            a4(2,i,1) = 0.
          endif
        end do
      else if (iv == 2) then
        do i = i1, i2
          a4(2,i,1) = a4(1,i,1)
          a4(3,i,1) = a4(1,i,1)
          a4(4,i,1) = 0.
        end do
      endif
      if (iv /= 2) then
        do i = i1, i2
          a4(4,i,1) = 3.*(2.*a4(1,i,1)-(a4(2,i,1)+a4(3,i,1)))
        end do
        call cs_limiters( im,extm(i1,1),a4(1,i1,1),1 )
      endif
      do i = i1, i2
        a4(4,i,2) = 3.*(2.*a4(1,i,2)-(a4(2,i,2)+a4(3,i,2)))
      end do
      call cs_limiters( im,extm(i1,2),a4(1,i1,2),2 )
      do ka1 = 3, km-2
        if (abs(kord) < 9) then
          do i = i1, i2
            pmp_1 = a4(1,i,ka1)-2.*gam(i,ka1+1)
            lac_1 = pmp_1+1.5*gam(i,ka1+2)
            a4(2,i,ka1) = min(max(a4(2,i,ka1),min(a4(1,i,ka1),pmp_1,lac_1)),max(a4(1,i,ka1),pmp_1,lac_1))
            pmp_2 = a4(1,i,ka1)+2.*gam(i,ka1)
            lac_2 = pmp_2-1.5*gam(i,ka1-1)
            a4(3,i,ka1) = min(max(a4(3,i,ka1),min(a4(1,i,ka1),pmp_2,lac_2)),max(a4(1,i,ka1),pmp_2,lac_2))
            a4(4,i,ka1) = 3.*(2.*a4(1,i,ka1)-(a4(2,i,ka1)+a4(3,i,ka1)))
          end do
        else if (abs(kord) == 9) then
          do i = i1, i2
            if (extm(i,ka1) .and. extm(i,ka1-1)) then
              a4(2,i,ka1) = a4(1,i,ka1)
              a4(3,i,ka1) = a4(1,i,ka1)
              a4(4,i,ka1) = 0.
            else if (extm(i,ka1) .and. extm(i,ka1+1)) then
              a4(2,i,ka1) = a4(1,i,ka1)
              a4(3,i,ka1) = a4(1,i,ka1)
              a4(4,i,ka1) = 0.
            else if (extm(i,ka1) .and. a4(1,i,ka1) < qmin) then
              a4(2,i,ka1) = a4(1,i,ka1)
              a4(3,i,ka1) = a4(1,i,ka1)
              a4(4,i,ka1) = 0.
            else
