              a5f_ad = a4_ad(3,i,k)*(0.5+sign(0.5,a5h-a5f))
              a5h_ad = a4_ad(3,i,k)*(0.5-sign(0.5,a5h-a5f))
              a5g_ad = a5h_ad*(0.5+sign(0.5,a5g-lac_2))
              lac_2_ad = lac_2_ad+a5h_ad*(0.5-sign(0.5,a5g-lac_2))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a5g_ad*(0.5+sign(0.5,a4(1,i,k)-pmp_2))
              pmp_2_ad = pmp_2_ad+a5g_ad*(0.5-sign(0.5,a4(1,i,k)-pmp_2))
              a4_ad(3,i,k) = a5f_ad*(0.5+sign(0.5,a4(3,i,k)-a5e))
              a5e_ad = a5f_ad*(0.5-sign(0.5,a4(3,i,k)-a5e))
              a5d_ad = a5e_ad*(0.5+sign(0.5,lac_2-a5d))
              lac_2_ad = lac_2_ad+a5e_ad*(0.5-sign(0.5,lac_2-a5d))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a5d_ad*(0.5+sign(0.5,pmp_2-a4(1,i,k)))
              pmp_2_ad = pmp_2_ad+a5d_ad*(0.5-sign(0.5,pmp_2-a4(1,i,k)))
              gam_ad(i,k-1) = gam_ad(i,k-1)-1.5*lac_2_ad
              pmp_2_ad = pmp_2_ad+lac_2_ad
              lac_2_ad = 0.
              a4_ad(1,i,k) = a4_ad(1,i,k)+pmp_2_ad
              gam_ad(i,k) = gam_ad(i,k)+2*pmp_2_ad
              pmp_2_ad = 0.
              a4 = a5n(:,:,:)
              a5i = min(a4(1,i,k),pmp_1)
              a5j = min(a5i,lac_1)
              a5k = max(a4(2,i,k),a5j)
              a5l = max(a4(1,i,k),pmp_1)
              a5m = max(a5l,lac_1)
              a5j_ad = 0.
              a5k_ad = a4_ad(2,i,k)*(0.5+sign(0.5,a5m-a5k))
              a5m_ad = a4_ad(2,i,k)*(0.5-sign(0.5,a5m-a5k))
              a5l_ad = a5m_ad*(0.5+sign(0.5,a5l-lac_1))
              lac_1_ad = lac_1_ad+a5m_ad*(0.5-sign(0.5,a5l-lac_1))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a5l_ad*(0.5+sign(0.5,a4(1,i,k)-pmp_1))
              pmp_1_ad = pmp_1_ad+a5l_ad*(0.5-sign(0.5,a4(1,i,k)-pmp_1))
              a4_ad(2,i,k) = a5k_ad*(0.5+sign(0.5,a4(2,i,k)-a5j))
              a5j_ad = a5k_ad*(0.5-sign(0.5,a4(2,i,k)-a5j))
              a5i_ad = a5j_ad*(0.5+sign(0.5,lac_1-a5i))
              lac_1_ad = lac_1_ad+a5j_ad*(0.5-sign(0.5,lac_1-a5i))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a5i_ad*(0.5+sign(0.5,pmp_1-a4(1,i,k)))
              pmp_1_ad = pmp_1_ad+a5i_ad*(0.5-sign(0.5,pmp_1-a4(1,i,k)))
              gam_ad(i,k+2) = gam_ad(i,k+2)+1.5*lac_1_ad
              pmp_1_ad = pmp_1_ad+lac_1_ad
              lac_1_ad = 0.
              a4_ad(1,i,k) = a4_ad(1,i,k)+pmp_1_ad
              gam_ad(i,k+1) = gam_ad(i,k+1)-2*pmp_1_ad
              pmp_1_ad = 0.
            endif
          endif
          a5n(:,:,:) = a4
        end do
      else if (abs(kord) == 12) then
        do i = i1, i2
          lac_1_ad = 0.
          lac_2_ad = 0.
          pmp_1_ad = 0.
          pmp_2_ad = 0.
!$taf INCOMPLETE a4
          if (extm(i,k)) then
            a4_ad(4,i,k) = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(3,i,k)
            a4_ad(3,i,k) = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(2,i,k)
            a4_ad(2,i,k) = 0.
          else
!$taf INCOMPLETE a4
            a4(4,i,k) = 6.*a4(1,i,k)-3.*(a4(2,i,k)+a4(3,i,k))
!$taf INCOMPLETE a4
            if (abs(a4(4,i,k)) > abs(a4(2,i,k)-a4(3,i,k))) then
!$taf INCOMPLETE a4
              pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
              lac_1 = pmp_1+1.5*gam(i,k+2)
              a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
              pmp_2 = a4(1,i,k)+2.*gam(i,k)
              lac_2 = pmp_2-1.5*gam(i,k-1)
              a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
              a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
              a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
              a4_ad(4,i,k) = 0.
              a43 = min(a4(1,i,k),pmp_2)
              a44 = min(a43,lac_2)
              a45 = max(a4(3,i,k),a44)
              a46 = max(a4(1,i,k),pmp_2)
              a47 = max(a46,lac_2)
              a44_ad = 0.
              a45_ad = a4_ad(3,i,k)*(0.5+sign(0.5,a47-a45))
              a47_ad = a4_ad(3,i,k)*(0.5-sign(0.5,a47-a45))
              a46_ad = a47_ad*(0.5+sign(0.5,a46-lac_2))
              lac_2_ad = lac_2_ad+a47_ad*(0.5-sign(0.5,a46-lac_2))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a46_ad*(0.5+sign(0.5,a4(1,i,k)-pmp_2))
              pmp_2_ad = pmp_2_ad+a46_ad*(0.5-sign(0.5,a4(1,i,k)-pmp_2))
              a4_ad(3,i,k) = a45_ad*(0.5+sign(0.5,a4(3,i,k)-a44))
              a44_ad = a45_ad*(0.5-sign(0.5,a4(3,i,k)-a44))
              a43_ad = a44_ad*(0.5+sign(0.5,lac_2-a43))
              lac_2_ad = lac_2_ad+a44_ad*(0.5-sign(0.5,lac_2-a43))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a43_ad*(0.5+sign(0.5,pmp_2-a4(1,i,k)))
              pmp_2_ad = pmp_2_ad+a43_ad*(0.5-sign(0.5,pmp_2-a4(1,i,k)))
              gam_ad(i,k-1) = gam_ad(i,k-1)-1.5*lac_2_ad
              pmp_2_ad = pmp_2_ad+lac_2_ad
              lac_2_ad = 0.
              a4_ad(1,i,k) = a4_ad(1,i,k)+pmp_2_ad
              gam_ad(i,k) = gam_ad(i,k)+2*pmp_2_ad
              pmp_2_ad = 0.
              a4 = a4s(:,:,:)
              a4(4,i,k) = 6.*a4(1,i,k)-3.*(a4(2,i,k)+a4(3,i,k))
              a48 = min(a4(1,i,k),pmp_1)
              a49 = min(a48,lac_1)
              a5a = max(a4(2,i,k),a49)
              a5b = max(a4(1,i,k),pmp_1)
              a5c = max(a5b,lac_1)
              a49_ad = 0.
              a5a_ad = a4_ad(2,i,k)*(0.5+sign(0.5,a5c-a5a))
              a5c_ad = a4_ad(2,i,k)*(0.5-sign(0.5,a5c-a5a))
              a5b_ad = a5c_ad*(0.5+sign(0.5,a5b-lac_1))
              lac_1_ad = lac_1_ad+a5c_ad*(0.5-sign(0.5,a5b-lac_1))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a5b_ad*(0.5+sign(0.5,a4(1,i,k)-pmp_1))
              pmp_1_ad = pmp_1_ad+a5b_ad*(0.5-sign(0.5,a4(1,i,k)-pmp_1))
              a4_ad(2,i,k) = a5a_ad*(0.5+sign(0.5,a4(2,i,k)-a49))
              a49_ad = a5a_ad*(0.5-sign(0.5,a4(2,i,k)-a49))
              a48_ad = a49_ad*(0.5+sign(0.5,lac_1-a48))
              lac_1_ad = lac_1_ad+a49_ad*(0.5-sign(0.5,lac_1-a48))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a48_ad*(0.5+sign(0.5,pmp_1-a4(1,i,k)))
              pmp_1_ad = pmp_1_ad+a48_ad*(0.5-sign(0.5,pmp_1-a4(1,i,k)))
              gam_ad(i,k+2) = gam_ad(i,k+2)+1.5*lac_1_ad
              pmp_1_ad = pmp_1_ad+lac_1_ad
              lac_1_ad = 0.
              a4_ad(1,i,k) = a4_ad(1,i,k)+pmp_1_ad
              gam_ad(i,k+1) = gam_ad(i,k+1)-2*pmp_1_ad
              pmp_1_ad = 0.
            endif
            a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
            a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
            a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
            a4_ad(4,i,k) = 0.
          endif
        end do
      else if (abs(kord) == 13) then
        do i = i1, i2
          a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
          a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
          a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
          a4_ad(4,i,k) = 0.
        end do
        do i = i1, i2
          if (ext6(i,k)) then
