          a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
          a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
          a4_ad(4,i,k) = 0.
        end do
        do i = i1, i2
          lac_1_ad = 0.
          lac_2_ad = 0.
          pmp_1_ad = 0.
          pmp_2_ad = 0.
!$taf INCOMPLETE a4
          if (ext5(i,k) .and. ext5(i,k-1)) then
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(3,i,k)
            a4_ad(3,i,k) = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(2,i,k)
            a4_ad(2,i,k) = 0.
          else if (ext5(i,k) .and. ext5(i,k+1)) then
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(3,i,k)
            a4_ad(3,i,k) = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(2,i,k)
            a4_ad(2,i,k) = 0.
          else if (ext5(i,k) .and. a4(1,i,k) < qmin) then
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(3,i,k)
            a4_ad(3,i,k) = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(2,i,k)
            a4_ad(2,i,k) = 0.
          else if (ext6(i,k)) then
!$taf INCOMPLETE a4
            pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
            lac_1 = pmp_1+1.5*gam(i,k+2)
            a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
            pmp_2 = a4(1,i,k)+2.*gam(i,k)
            lac_2 = pmp_2-1.5*gam(i,k-1)
            a4t = min(a4(1,i,k),pmp_2)
            a4u = min(a4t,lac_2)
            a4v = max(a4(3,i,k),a4u)
            a4w = max(a4(1,i,k),pmp_2)
            a4x = max(a4w,lac_2)
            a4u_ad = 0.
            a4v_ad = a4_ad(3,i,k)*(0.5+sign(0.5,a4x-a4v))
            a4x_ad = a4_ad(3,i,k)*(0.5-sign(0.5,a4x-a4v))
            a4w_ad = a4x_ad*(0.5+sign(0.5,a4w-lac_2))
            lac_2_ad = lac_2_ad+a4x_ad*(0.5-sign(0.5,a4w-lac_2))
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4w_ad*(0.5+sign(0.5,a4(1,i,k)-pmp_2))
            pmp_2_ad = pmp_2_ad+a4w_ad*(0.5-sign(0.5,a4(1,i,k)-pmp_2))
            a4_ad(3,i,k) = a4v_ad*(0.5+sign(0.5,a4(3,i,k)-a4u))
            a4u_ad = a4v_ad*(0.5-sign(0.5,a4(3,i,k)-a4u))
            a4t_ad = a4u_ad*(0.5+sign(0.5,lac_2-a4t))
            lac_2_ad = lac_2_ad+a4u_ad*(0.5-sign(0.5,lac_2-a4t))
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4t_ad*(0.5+sign(0.5,pmp_2-a4(1,i,k)))
            pmp_2_ad = pmp_2_ad+a4t_ad*(0.5-sign(0.5,pmp_2-a4(1,i,k)))
            gam_ad(i,k-1) = gam_ad(i,k-1)-1.5*lac_2_ad
            pmp_2_ad = pmp_2_ad+lac_2_ad
            lac_2_ad = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+pmp_2_ad
            gam_ad(i,k) = gam_ad(i,k)+2*pmp_2_ad
            pmp_2_ad = 0.
            a4 = a4s(:,:,:)
            a4y = min(a4(1,i,k),pmp_1)
            a4z = min(a4y,lac_1)
            a40 = max(a4(2,i,k),a4z)
            a41 = max(a4(1,i,k),pmp_1)
            a42 = max(a41,lac_1)
            a4z_ad = 0.
            a40_ad = a4_ad(2,i,k)*(0.5+sign(0.5,a42-a40))
            a42_ad = a4_ad(2,i,k)*(0.5-sign(0.5,a42-a40))
            a41_ad = a42_ad*(0.5+sign(0.5,a41-lac_1))
            lac_1_ad = lac_1_ad+a42_ad*(0.5-sign(0.5,a41-lac_1))
            a4_ad(1,i,k) = a4_ad(1,i,k)+a41_ad*(0.5+sign(0.5,a4(1,i,k)-pmp_1))
            pmp_1_ad = pmp_1_ad+a41_ad*(0.5-sign(0.5,a4(1,i,k)-pmp_1))
            a4_ad(2,i,k) = a40_ad*(0.5+sign(0.5,a4(2,i,k)-a4z))
            a4z_ad = a40_ad*(0.5-sign(0.5,a4(2,i,k)-a4z))
            a4y_ad = a4z_ad*(0.5+sign(0.5,lac_1-a4y))
            lac_1_ad = lac_1_ad+a4z_ad*(0.5-sign(0.5,lac_1-a4y))
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4y_ad*(0.5+sign(0.5,pmp_1-a4(1,i,k)))
            pmp_1_ad = pmp_1_ad+a4y_ad*(0.5-sign(0.5,pmp_1-a4(1,i,k)))
            gam_ad(i,k+2) = gam_ad(i,k+2)+1.5*lac_1_ad
            pmp_1_ad = pmp_1_ad+lac_1_ad
            lac_1_ad = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+pmp_1_ad
            gam_ad(i,k+1) = gam_ad(i,k+1)-2*pmp_1_ad
            pmp_1_ad = 0.
          endif
        end do
      else if (abs(kord) == 16) then
        do i = i1, i2
          a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
          a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
          a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
          a4_ad(4,i,k) = 0.
        end do
        do i = i1, i2
          lac_1_ad = 0.
          lac_2_ad = 0.
          pmp_1_ad = 0.
          pmp_2_ad = 0.
!$taf INCOMPLETE a4
          if (ext5(i,k)) then
!$taf INCOMPLETE a4
            if (ext5(i,k-1) .or. ext5(i,k+1)) then
              a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(3,i,k)
              a4_ad(3,i,k) = 0.
              a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(2,i,k)
              a4_ad(2,i,k) = 0.
            else if (ext6(i,k-1) .or. ext6(i,k+1)) then
!$taf INCOMPLETE a4
              pmp_1 = a4(1,i,k)-2.*gam(i,k+1)
              lac_1 = pmp_1+1.5*gam(i,k+2)
              a4(2,i,k) = min(max(a4(2,i,k),min(a4(1,i,k),pmp_1,lac_1)),max(a4(1,i,k),pmp_1,lac_1))
              pmp_2 = a4(1,i,k)+2.*gam(i,k)
              lac_2 = pmp_2-1.5*gam(i,k-1)
              a4i = min(a4(1,i,k),pmp_2)
              a4j = min(a4i,lac_2)
              a4k = max(a4(3,i,k),a4j)
              a4l = max(a4(1,i,k),pmp_2)
              a4m = max(a4l,lac_2)
              a4j_ad = 0.
              a4k_ad = a4_ad(3,i,k)*(0.5+sign(0.5,a4m-a4k))
              a4m_ad = a4_ad(3,i,k)*(0.5-sign(0.5,a4m-a4k))
              a4l_ad = a4m_ad*(0.5+sign(0.5,a4l-lac_2))
              lac_2_ad = lac_2_ad+a4m_ad*(0.5-sign(0.5,a4l-lac_2))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a4l_ad*(0.5+sign(0.5,a4(1,i,k)-pmp_2))
              pmp_2_ad = pmp_2_ad+a4l_ad*(0.5-sign(0.5,a4(1,i,k)-pmp_2))
              a4_ad(3,i,k) = a4k_ad*(0.5+sign(0.5,a4(3,i,k)-a4j))
              a4j_ad = a4k_ad*(0.5-sign(0.5,a4(3,i,k)-a4j))
              a4i_ad = a4j_ad*(0.5+sign(0.5,lac_2-a4i))
              lac_2_ad = lac_2_ad+a4j_ad*(0.5-sign(0.5,lac_2-a4i))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a4i_ad*(0.5+sign(0.5,pmp_2-a4(1,i,k)))
              pmp_2_ad = pmp_2_ad+a4i_ad*(0.5-sign(0.5,pmp_2-a4(1,i,k)))
              gam_ad(i,k-1) = gam_ad(i,k-1)-1.5*lac_2_ad
              pmp_2_ad = pmp_2_ad+lac_2_ad
              lac_2_ad = 0.
              a4_ad(1,i,k) = a4_ad(1,i,k)+pmp_2_ad
              gam_ad(i,k) = gam_ad(i,k)+2*pmp_2_ad
              pmp_2_ad = 0.
              a4 = a4s(:,:,:)
              a4n = min(a4(1,i,k),pmp_1)
              a4o = min(a4n,lac_1)
              a4p = max(a4(2,i,k),a4o)
              a4q = max(a4(1,i,k),pmp_1)
              a4r = max(a4q,lac_1)
              a4o_ad = 0.
              a4p_ad = a4_ad(2,i,k)*(0.5+sign(0.5,a4r-a4p))
              a4r_ad = a4_ad(2,i,k)*(0.5-sign(0.5,a4r-a4p))
              a4q_ad = a4r_ad*(0.5+sign(0.5,a4q-lac_1))
              lac_1_ad = lac_1_ad+a4r_ad*(0.5-sign(0.5,a4q-lac_1))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a4q_ad*(0.5+sign(0.5,a4(1,i,k)-pmp_1))
              pmp_1_ad = pmp_1_ad+a4q_ad*(0.5-sign(0.5,a4(1,i,k)-pmp_1))
              a4_ad(2,i,k) = a4p_ad*(0.5+sign(0.5,a4(2,i,k)-a4o))
              a4o_ad = a4p_ad*(0.5-sign(0.5,a4(2,i,k)-a4o))
              a4n_ad = a4o_ad*(0.5+sign(0.5,lac_1-a4n))
              lac_1_ad = lac_1_ad+a4o_ad*(0.5-sign(0.5,lac_1-a4n))
              a4_ad(1,i,k) = a4_ad(1,i,k)+a4n_ad*(0.5+sign(0.5,pmp_1-a4(1,i,k)))
              pmp_1_ad = pmp_1_ad+a4n_ad*(0.5-sign(0.5,pmp_1-a4(1,i,k)))
              gam_ad(i,k+2) = gam_ad(i,k+2)+1.5*lac_1_ad
              pmp_1_ad = pmp_1_ad+lac_1_ad
              lac_1_ad = 0.
              a4_ad(1,i,k) = a4_ad(1,i,k)+pmp_1_ad
              gam_ad(i,k+1) = gam_ad(i,k+1)-2*pmp_1_ad
              pmp_1_ad = 0.
            endif
          endif
        end do
      else
        do i = i1, i2
          if (ext5(i,k) .and. (ext5(i,k-1) .or. ext5(i,k+1) .or. a4(1,i,k) < qmin)) then
            a4_ad(4,i,k) = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(3,i,k)
            a4_ad(3,i,k) = 0.
            a4_ad(1,i,k) = a4_ad(1,i,k)+a4_ad(2,i,k)
            a4_ad(2,i,k) = 0.
          else
            a4_ad(3,i,k) = a4_ad(3,i,k)-3*a4_ad(4,i,k)
            a4_ad(2,i,k) = a4_ad(2,i,k)-3*a4_ad(4,i,k)
            a4_ad(1,i,k) = a4_ad(1,i,k)+6*a4_ad(4,i,k)
            a4_ad(4,i,k) = 0.
          endif
        end do
      endif
    end do
    do k = 1, km
      do i = i1, i2
        a4(2,i,k) = q(i,k)
        a4(3,i,k) = q(i,k+1)
      end do
    end do
    do k = 1, km
      if (abs(kord) > 9) then
        do i = i1, i2
          x0 = 2.*a4(1,i,k)-(a4(2,i,k)+a4(3,i,k))
          a4(4,i,k) = 3.*x0
        end do
      endif
    end do
    if (iv == 0) then
      do i = i1, i2
        a4(2,i,1) = max(0.,a4(2,i,1))
