        q(i,1) = ((grat+grat)*(grat+1.)*a4(1,i,1)+a4(1,i,2))/bet
        gam(i,1) = (1.+grat*(grat+1.5))/bet
      end do
      do k = 2, km
        do i = i1, i2
          d4(i) = delp(i,k-1)/delp(i,k)
